export const GITHUB_INSTALL_MESSAGE = "github-app-installed";

export type GithubInstallMessage = {
  type: typeof GITHUB_INSTALL_MESSAGE;
  error?: string;
};

export type GithubRepoOption = {
  id: number;
  fullName: string;
  private: boolean;
  defaultBranch: string;
};

export type GithubConnection =
  | { connected: false }
  | {
      connected: true;
      installationId: number;
      accountLogin: string;
      repos: GithubRepoOption[];
    };

export type GithubSelection = {
  installationId: number;
  fullName: string;
  defaultBranch: string;
  branch: string;
};

export function parseRepoFullName(fullName: string) {
  const match = /^([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+)$/.exec(fullName);
  if (!match) return null;
  return { owner: match[1], repo: match[2] };
}

export function isGithubSelection(value: unknown): value is GithubSelection {
  if (!value || typeof value !== "object") return false;
  const selection = value as Partial<GithubSelection>;
  return (
    typeof selection.installationId === "number" &&
    Number.isInteger(selection.installationId) &&
    typeof selection.fullName === "string" &&
    parseRepoFullName(selection.fullName) !== null &&
    typeof selection.defaultBranch === "string" &&
    selection.defaultBranch.length > 0 &&
    typeof selection.branch === "string" &&
    selection.branch.length > 0
  );
}

const missingAppMessage =
  "Add GITHUB_APP_ID, GITHUB_APP_SLUG, and GITHUB_APP_PRIVATE_KEY to web/.env.";

export function githubAppConfig() {
  const appId = process.env.GITHUB_APP_ID?.trim() ?? "";
  const slug = process.env.GITHUB_APP_SLUG?.trim() ?? "";
  const privateKey = normalizePrivateKey(
    process.env.GITHUB_APP_PRIVATE_KEY ?? "",
  );

  if (!appId || !slug || !privateKey.includes("BEGIN")) {
    throw new Error(missingAppMessage);
  }

  return { appId, slug, privateKey };
}

export function githubInstallUrl(state: string) {
  const { slug } = githubAppConfig();
  const url = new URL(`https://github.com/apps/${slug}/installations/new`);
  url.searchParams.set("state", state);
  return url;
}

function normalizePrivateKey(raw: string) {
  let key = raw.trim();
  if (
    (key.startsWith('"') && key.endsWith('"')) ||
    (key.startsWith("'") && key.endsWith("'"))
  ) {
    key = key.slice(1, -1);
  }
  return key.replace(/\\n/g, "\n");
}

import {
  createHmac,
  randomBytes,
  timingSafeEqual,
} from "node:crypto";

export const GITHUB_STATE_COOKIE = "ff-github-state";

type StatePayload = {
  userId: string;
  nonce: string;
  exp: number;
};

export function githubStateCookieOptions() {
  return {
    path: "/api/github",
    httpOnly: true,
    sameSite: "lax" as const,
    secure: process.env.NODE_ENV === "production",
    maxAge: 10 * 60,
  };
}

export function createGithubState(userId: string) {
  const payload: StatePayload = {
    userId,
    nonce: randomBytes(16).toString("base64url"),
    exp: Date.now() + 10 * 60 * 1000,
  };
  const body = Buffer.from(JSON.stringify(payload)).toString("base64url");
  return `${body}.${sign(body)}`;
}

export function readGithubState(state: string, userId: string) {
  const [body, signature, extra] = state.split(".");
  if (!body || !signature || extra) return null;
  if (!safeEqual(signature, sign(body))) return null;

  try {
    const payload = JSON.parse(
      Buffer.from(body, "base64url").toString(),
    ) as Partial<StatePayload>;
    if (payload.userId !== userId) return null;
    if (typeof payload.exp !== "number" || payload.exp < Date.now()) return null;
    return payload;
  } catch {
    return null;
  }
}

export function readRequestCookie(request: Request, name: string) {
  const header = request.headers.get("cookie") ?? "";
  for (const part of header.split(";")) {
    const [key, ...rest] = part.trim().split("=");
    if (key === name) return decodeURIComponent(rest.join("="));
  }
  return "";
}

function sign(body: string) {
  const secret = process.env.COOKIE_SECRET_KEY;
  if (!secret) throw new Error("Missing COOKIE_SECRET_KEY.");
  return createHmac("sha256", secret).update(body).digest("base64url");
}

function safeEqual(a: string, b: string) {
  const left = Buffer.from(a);
  const right = Buffer.from(b);
  return left.length === right.length && timingSafeEqual(left, right);
}

import { createSign } from "node:crypto";
import { githubAppConfig } from "@/lib/github/config";
import {
  parseRepoFullName,
  type GithubRepoOption,
} from "@/lib/github/types";

const tokenCache = new Map<number, { token: string; expiresAt: number }>();

export class GithubRequestError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
  }
}

export async function getInstallationAccount(installationId: number) {
  const body = await githubJson(
    `/app/installations/${installationId}`,
    appJwt(),
  );
  return readAccount(body);
}

export async function listInstallationRepos(installationId: number) {
  const token = await installationToken(installationId);
  const repos: GithubRepoOption[] = [];
  let url = "https://api.github.com/installation/repositories?per_page=100";

  for (let page = 0; page < 10 && url; page += 1) {
    const response = await githubFetch(url, token);
    const body = (await response.json()) as { repositories?: unknown };
    if (Array.isArray(body.repositories)) {
      for (const repo of body.repositories) {
        const option = toRepoOption(repo);
        if (option) repos.push(option);
      }
    }
    url = nextLink(response.headers.get("link"));
  }

  repos.sort((a, b) => a.fullName.localeCompare(b.fullName));
  return repos;
}

export async function listBranches(installationId: number, fullName: string) {
  const repo = parseRepoFullName(fullName);
  if (!repo) throw new GithubRequestError("Choose a repository.", 400);

  const token = await installationToken(installationId);
  const names: string[] = [];
  let url = `https://api.github.com/repos/${repo.owner}/${repo.repo}/branches?per_page=100`;

  for (let page = 0; page < 10 && url; page += 1) {
    const response = await githubFetch(url, token);
    const body = (await response.json()) as unknown;
    if (Array.isArray(body)) {
      for (const branch of body) {
        if (
          branch &&
          typeof branch === "object" &&
          typeof (branch as { name?: unknown }).name === "string"
        ) {
          names.push((branch as { name: string }).name);
        }
      }
    }
    url = nextLink(response.headers.get("link"));
  }

  return [...new Set(names)].sort((a, b) => a.localeCompare(b));
}

export async function assertRepoBranch(input: {
  installationId: number;
  fullName: string;
  branch: string;
}) {
  const repo = parseRepoFullName(input.fullName);
  if (!repo) throw new GithubRequestError("Choose a repository.", 400);

  const token = await installationToken(input.installationId);
  const details = await githubJson(
    `/repos/${repo.owner}/${repo.repo}`,
    token,
  );
  const defaultBranch =
    details &&
    typeof details === "object" &&
    typeof (details as { default_branch?: unknown }).default_branch === "string"
      ? (details as { default_branch: string }).default_branch
      : "";

  await githubJson(
    `/repos/${repo.owner}/${repo.repo}/branches/${encodeURIComponent(input.branch)}`,
    token,
  );

  return { defaultBranch };
}

async function installationToken(installationId: number) {
  const cached = tokenCache.get(installationId);
  if (cached && cached.expiresAt > Date.now() + 60_000) return cached.token;

  const body = await githubJson(
    `/app/installations/${installationId}/access_tokens`,
    appJwt(),
    "POST",
  );
  if (
    !body ||
    typeof body !== "object" ||
    typeof (body as { token?: unknown }).token !== "string"
  ) {
    throw new GithubRequestError("GitHub did not return an access token.", 502);
  }

  const token = (body as { token: string }).token;
  const expiresAtRaw = (body as { expires_at?: unknown }).expires_at;
  const expiresAt =
    typeof expiresAtRaw === "string" ? Date.parse(expiresAtRaw) : Date.now();
  tokenCache.set(installationId, {
    token,
    expiresAt: Number.isNaN(expiresAt) ? Date.now() + 5 * 60_000 : expiresAt,
  });
  return token;
}

function appJwt() {
  const { appId, privateKey } = githubAppConfig();
  const now = Math.floor(Date.now() / 1000);
  const header = base64Url(JSON.stringify({ alg: "RS256", typ: "JWT" }));
  const payload = base64Url(
    JSON.stringify({ iat: now - 60, exp: now + 9 * 60, iss: appId }),
  );
  const data = `${header}.${payload}`;
  const signer = createSign("RSA-SHA256");
  signer.update(data);
  return `${data}.${signer.sign(privateKey).toString("base64url")}`;
}

async function githubJson(path: string, token: string, method: "GET" | "POST" = "GET") {
  const response = await githubFetch(
    path.startsWith("https://") ? path : `https://api.github.com${path}`,
    token,
    method,
  );
  return response.json() as Promise<unknown>;
}

async function githubFetch(url: string, token: string, method: "GET" | "POST" = "GET") {
  const response = await fetch(url, {
    method,
    cache: "no-store",
    headers: {
      Accept: "application/vnd.github+json",
      Authorization: `Bearer ${token}`,
      "User-Agent": "friction-fixer",
      "X-GitHub-Api-Version": "2022-11-28",
      ...(method === "POST" ? { "Content-Type": "application/json" } : {}),
    },
    body: method === "POST" ? "{}" : undefined,
  });

  if (!response.ok) {
    let message = "GitHub could not complete that request.";
    try {
      const body = (await response.json()) as { message?: unknown };
      if (typeof body.message === "string" && body.message) message = body.message;
    } catch {
      message = response.statusText || message;
    }
    throw new GithubRequestError(message, response.status);
  }

  return response;
}

function readAccount(body: unknown) {
  if (!body || typeof body !== "object") return null;
  const account = (body as { account?: { login?: unknown; type?: unknown } })
    .account;
  if (!account || typeof account.login !== "string" || !account.login) {
    return null;
  }
  return {
    login: account.login,
    type: typeof account.type === "string" ? account.type : "User",
  };
}

function toRepoOption(value: unknown): GithubRepoOption | null {
  if (!value || typeof value !== "object") return null;
  const repo = value as {
    id?: unknown;
    full_name?: unknown;
    private?: unknown;
    default_branch?: unknown;
  };
  if (
    typeof repo.id !== "number" ||
    typeof repo.full_name !== "string" ||
    typeof repo.private !== "boolean" ||
    typeof repo.default_branch !== "string"
  ) {
    return null;
  }
  if (!parseRepoFullName(repo.full_name)) return null;
  return {
    id: repo.id,
    fullName: repo.full_name,
    private: repo.private,
    defaultBranch: repo.default_branch,
  };
}

function nextLink(header: string | null) {
  if (!header) return "";
  const part = header.split(",").find((item) => item.includes('rel="next"'));
  return part?.match(/<([^>]+)>/)?.[1] ?? "";
}

function base64Url(value: string) {
  return Buffer.from(value).toString("base64url");
}

export type GithubInstallationRecord = {
  userId: string;
  installationId: number;
  accountLogin: string;
  accountType: string;
  createdAt: unknown;
  updatedAt: unknown;
};

import type { AnalyticsProvider, ProjectGoal } from "@/components/onboarding/logic";

export type ProjectRecord = {
  userId: string;
  siteUrl: string;
  analyticsProvider: AnalyticsProvider;
  goal: ProjectGoal;
  repository: string;
  branch: string;
  installationId: number;
  accountLogin: string;
  createdAt: unknown;
  updatedAt: unknown;
};

import { FieldValue } from "firebase-admin/firestore";
import { db } from "@/lib/db/firebase";
import { COLLECTIONS } from "@/lib/db/collections";
import type { GithubInstallationRecord } from "@/lib/db/schema/github-installation";

export async function getGithubInstallation(userId: string) {
  const snap = await db()
    .collection(COLLECTIONS.GITHUB_INSTALLATIONS)
    .doc(userId)
    .get();

  if (!snap.exists) return null;

  const data = snap.data();
  if (!data) return null;

  const installationId = Number(data.installationId);
  if (!Number.isInteger(installationId) || installationId <= 0) return null;

  const record: GithubInstallationRecord = {
    userId,
    installationId,
    accountLogin: typeof data.accountLogin === "string" ? data.accountLogin : "",
    accountType: typeof data.accountType === "string" ? data.accountType : "User",
    createdAt: data.createdAt,
    updatedAt: data.updatedAt,
  };

  return record;
}

export async function saveGithubInstallation(input: {
  userId: string;
  installationId: number;
  accountLogin: string;
  accountType: string;
}) {
  const ref = db().collection(COLLECTIONS.GITHUB_INSTALLATIONS).doc(input.userId);
  const snap = await ref.get();

  await ref.set({
    userId: input.userId,
    installationId: input.installationId,
    accountLogin: input.accountLogin,
    accountType: input.accountType,
    createdAt: snap.exists
      ? (snap.get("createdAt") ?? FieldValue.serverTimestamp())
      : FieldValue.serverTimestamp(),
    updatedAt: FieldValue.serverTimestamp(),
  });
}

export async function deleteGithubInstallation(userId: string) {
  await db().collection(COLLECTIONS.GITHUB_INSTALLATIONS).doc(userId).delete();
}

import { FieldValue } from "firebase-admin/firestore";
import type { AnalyticsProvider, ProjectGoal } from "@/components/onboarding/logic";
import { db } from "@/lib/db/firebase";
import { COLLECTIONS } from "@/lib/db/collections";
import { OnboardingStatus } from "@/lib/db/schema/user";

export async function createProject(input: {
  userId: string;
  siteUrl: string;
  analyticsProvider: AnalyticsProvider;
  goal: ProjectGoal;
  repository: string;
  branch: string;
  installationId: number;
  accountLogin: string;
}) {
  const firestore = db();
  const projectRef = firestore.collection(COLLECTIONS.PROJECTS).doc();
  const userRef = firestore.collection(COLLECTIONS.USERS).doc(input.userId);
  const batch = firestore.batch();

  batch.set(projectRef, {
    userId: input.userId,
    siteUrl: input.siteUrl,
    analyticsProvider: input.analyticsProvider,
    goal: input.goal,
    repository: input.repository,
    branch: input.branch,
    installationId: input.installationId,
    accountLogin: input.accountLogin,
    createdAt: FieldValue.serverTimestamp(),
    updatedAt: FieldValue.serverTimestamp(),
  });

  batch.update(userRef, {
    "onboarding.status": OnboardingStatus.in_progress,
    "onboarding.projectId": projectRef.id,
    updatedAt: FieldValue.serverTimestamp(),
  });

  await batch.commit();
  return projectRef.id;
}

