import { NextResponse } from "next/server";
import { getServerUser } from "@/lib/auth/request-user";
import { githubInstallUrl } from "@/lib/github/config";
import {
  createGithubState,
  GITHUB_STATE_COOKIE,
  githubStateCookieOptions,
} from "@/lib/github/state";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  const origin = new URL(request.url).origin;
  const user = await getServerUser();

  if (!user) {
    return NextResponse.redirect(new URL("/auth?redirect=/onboarding", origin));
  }

  try {
    const state = createGithubState(user.userId);
    const response = NextResponse.redirect(githubInstallUrl(state));
    response.cookies.set(GITHUB_STATE_COOKIE, state, githubStateCookieOptions());
    return response;
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "GitHub could not be opened.";
    return redirectToConnected(origin, message);
  }
}

function redirectToConnected(origin: string, error: string) {
  const url = new URL("/onboarding/github/connected", origin);
  url.searchParams.set("error", error);
  return NextResponse.redirect(url);
}

import { NextResponse } from "next/server";
import { getServerUser } from "@/lib/auth/request-user";
import { getInstallationAccount } from "@/lib/github/app";
import { saveGithubInstallation } from "@/lib/db/github-installations";
import {
  GITHUB_STATE_COOKIE,
  githubStateCookieOptions,
  readGithubState,
  readRequestCookie,
} from "@/lib/github/state";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  const origin = new URL(request.url).origin;
  const url = new URL(request.url);
  const user = await getServerUser();

  if (!user) {
    return NextResponse.redirect(new URL("/auth?redirect=/onboarding", origin));
  }

  const setupAction = url.searchParams.get("setup_action");
  if (setupAction === "request") {
    return finish(
      origin,
      "Ask a GitHub owner to approve the Friction Fixer app.",
    );
  }

  const state = url.searchParams.get("state") ?? "";
  const cookie = readRequestCookie(request, GITHUB_STATE_COOKIE);
  if (!state || state !== cookie || !readGithubState(state, user.userId)) {
    return finish(origin, "GitHub connection expired. Try connecting again.");
  }

  const installationId = Number(url.searchParams.get("installation_id"));
  if (!Number.isInteger(installationId) || installationId <= 0) {
    return finish(origin, "GitHub did not return an installation.");
  }

  try {
    const account = await getInstallationAccount(installationId);
    if (!account) {
      return finish(origin, "GitHub did not return an account for that install.");
    }

    await saveGithubInstallation({
      userId: user.userId,
      installationId,
      accountLogin: account.login,
      accountType: account.type,
    });

    return finish(origin);
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Could not save the GitHub install.";
    return finish(origin, message);
  }
}

function finish(origin: string, error?: string) {
  const url = new URL("/onboarding/github/connected", origin);
  if (error) url.searchParams.set("error", error);
  const response = NextResponse.redirect(url);
  response.cookies.set(GITHUB_STATE_COOKIE, "", {
    ...githubStateCookieOptions(),
    maxAge: 0,
  });
  return response;
}

import { NextResponse } from "next/server";
import { getServerUser } from "@/lib/auth/request-user";
import { GithubRequestError, listInstallationRepos } from "@/lib/github/app";
import {
  deleteGithubInstallation,
  getGithubInstallation,
} from "@/lib/db/github-installations";
import type { GithubConnection } from "@/lib/github/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET() {
  const user = await getServerUser();
  if (!user) {
    return NextResponse.json({ error: "Sign in to continue." }, { status: 401 });
  }

  try {
    const installation = await getGithubInstallation(user.userId);
    if (!installation) {
      const body: GithubConnection = { connected: false };
      return NextResponse.json(body);
    }

    const repos = await listInstallationRepos(installation.installationId);
    const body: GithubConnection = {
      connected: true,
      installationId: installation.installationId,
      accountLogin: installation.accountLogin,
      repos,
    };
    return NextResponse.json(body);
  } catch (error) {
    if (error instanceof GithubRequestError && error.status === 404) {
      await deleteGithubInstallation(user.userId);
      const body: GithubConnection = { connected: false };
      return NextResponse.json(body);
    }

    const message =
      error instanceof Error ? error.message : "Could not load GitHub.";
    const status = error instanceof GithubRequestError ? error.status : 500;
    return NextResponse.json({ error: message }, { status });
  }
}

import { NextResponse } from "next/server";
import { getServerUser } from "@/lib/auth/request-user";
import { GithubRequestError, listBranches } from "@/lib/github/app";
import { getGithubInstallation } from "@/lib/db/github-installations";
import { parseRepoFullName } from "@/lib/github/types";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

export async function GET(request: Request) {
  const user = await getServerUser();
  if (!user) {
    return NextResponse.json({ error: "Sign in to continue." }, { status: 401 });
  }

  const fullName = new URL(request.url).searchParams.get("repo") ?? "";
  if (!parseRepoFullName(fullName)) {
    return NextResponse.json({ error: "Choose a repository." }, { status: 400 });
  }

  try {
    const installation = await getGithubInstallation(user.userId);
    if (!installation) {
      return NextResponse.json(
        { error: "Connect GitHub before choosing a branch." },
        { status: 409 },
      );
    }

    const branches = await listBranches(installation.installationId, fullName);
    return NextResponse.json({ branches });
  } catch (error) {
    const message =
      error instanceof Error ? error.message : "Could not load branches.";
    const status = error instanceof GithubRequestError ? error.status : 500;
    return NextResponse.json({ error: message }, { status });
  }
}

"use client";

import { useEffect } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import { GITHUB_INSTALL_MESSAGE } from "@/lib/github/types";

export function GithubConnected() {
  const router = useRouter();
  const params = useSearchParams();

  useEffect(() => {
    const error = params.get("error") ?? undefined;
    const payload = { type: GITHUB_INSTALL_MESSAGE, error };

    if (window.opener && !window.opener.closed) {
      window.opener.postMessage(payload, window.location.origin);
      window.close();
      return;
    }

    const next = new URL("/onboarding", window.location.origin);
    if (error) next.searchParams.set("github_error", error);
    else next.searchParams.set("github", "connected");
    router.replace(`${next.pathname}${next.search}`);
  }, [params, router]);

  return (
    <main className="grid min-h-svh place-items-center bg-background px-6 text-sm text-muted-foreground">
      Finishing the GitHub connection…
    </main>
  );
}

import { Suspense } from "react";
import type { Metadata } from "next";
import { GithubConnected } from "./github-connected";

export const metadata: Metadata = {
  title: "Connecting GitHub — Friction Fixer",
  robots: { index: false, follow: false },
};

export default function GithubConnectedPage() {
  return (
    <Suspense
      fallback={
        <main className="grid min-h-svh place-items-center bg-background px-6 text-sm text-muted-foreground">
          Finishing the GitHub connection…
        </main>
      }
    >
      <GithubConnected />
    </Suspense>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Check } from "lucide-react";
import { GithubIcon } from "@/components/icons/github-icon";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  GITHUB_INSTALL_MESSAGE,
  type GithubConnection,
  type GithubInstallMessage,
  type GithubSelection,
} from "@/lib/github/types";

export function GithubStep({
  selection,
  onSelectionChange,
}: {
  selection: GithubSelection | null;
  onSelectionChange: (value: GithubSelection | null) => void;
}) {
  const [connection, setConnection] = useState<GithubConnection | null>(null);
  const [branches, setBranches] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [branchesLoading, setBranchesLoading] = useState(false);
  const [authorizing, setAuthorizing] = useState(false);
  const [error, setError] = useState("");
  const [refreshKey, setRefreshKey] = useState(0);

  useEffect(() => {
    let cancelled = false;

    async function load() {
      setLoading(true);
      setError("");
      try {
        const next = await readJson<GithubConnection>("/api/github/connection");
        if (!cancelled) setConnection(next);
      } catch (loadError) {
        if (!cancelled) {
          setConnection({ connected: false });
          setError(messageFrom(loadError));
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    }

    void load();
    return () => {
      cancelled = true;
    };
  }, [refreshKey]);

  useEffect(() => {
    if (!connection?.connected) return;

    const match = selection
      ? connection.repos.find((repo) => repo.fullName === selection.fullName)
      : undefined;

    if (selection && !match) {
      onSelectionChange(null);
      return;
    }

    if (!selection && connection.repos.length === 1) {
      const repo = connection.repos[0];
      onSelectionChange({
        installationId: connection.installationId,
        fullName: repo.fullName,
        defaultBranch: repo.defaultBranch,
        branch: repo.defaultBranch,
      });
    }
  }, [connection, onSelectionChange, selection]);

  useEffect(() => {
    if (!selection?.fullName) {
      setBranches([]);
      return;
    }

    let cancelled = false;
    setBranchesLoading(true);

    readJson<{ branches: string[] }>(
      `/api/github/branches?repo=${encodeURIComponent(selection.fullName)}`,
    )
      .then((body) => {
        if (!cancelled) setBranches(body.branches);
      })
      .catch((branchError) => {
        if (!cancelled) setError(messageFrom(branchError));
      })
      .finally(() => {
        if (!cancelled) setBranchesLoading(false);
      });

    return () => {
      cancelled = true;
    };
  }, [selection?.fullName]);

  function connect() {
    setError("");
    const popup = window.open(
      "/api/github/install",
      "friction-fixer-github",
      "popup,width=980,height=760",
    );

    if (!popup) {
      window.location.assign("/api/github/install");
      return;
    }

    setAuthorizing(true);

    const onMessage = (event: MessageEvent) => {
      if (event.origin !== window.location.origin) return;
      if (event.source !== popup) return;
      if (!isInstallMessage(event.data)) return;
      cleanup();
      if (event.data.error) {
        setError(event.data.error);
        return;
      }
      onSelectionChange(null);
      setRefreshKey((value) => value + 1);
    };

    const timer = window.setInterval(() => {
      if (popup.closed) cleanup();
    }, 400);

    function cleanup() {
      window.clearInterval(timer);
      window.removeEventListener("message", onMessage);
      setAuthorizing(false);
    }

    window.addEventListener("message", onMessage);
  }

  const repos = connection?.connected ? connection.repos : [];
  const selectedRepo = repos.find((repo) => repo.fullName === selection?.fullName);
  const branchNames =
    selection && !branches.includes(selection.branch)
      ? [selection.branch, ...branches]
      : branches;

  return (
    <div className="grid gap-6">
      {loading && !connection?.connected ? (
        <p className="text-sm text-muted-foreground">Checking GitHub…</p>
      ) : null}

      {connection?.connected ? (
        <div className="grid gap-5">
          <div className="flex items-center justify-between gap-4 rounded-lg border border-border px-4 py-3">
            <div>
              <p className="text-sm font-semibold">{connection.accountLogin}</p>
              <p className="mt-1 text-sm text-muted-foreground">
                GitHub App connected
              </p>
            </div>
            <Button
              type="button"
              variant="ghost"
              disabled={authorizing}
              onClick={connect}
            >
              {authorizing ? "Waiting…" : "Change"}
            </Button>
          </div>

          {repos.length === 0 ? (
            <div className="grid gap-3">
              <p className="text-sm text-muted-foreground">
                This install can’t see a repository yet. Choose one on GitHub,
                then come back.
              </p>
              <Button type="button" variant="outline" onClick={connect}>
                <GithubIcon />
                Choose a repository
              </Button>
            </div>
          ) : (
            <>
              <div className="grid gap-2">
                <Label htmlFor="github-repo">Repository</Label>
                <Select
                  value={selection?.fullName ?? ""}
                  onValueChange={(value) => {
                    const repo = repos.find((item) => item.fullName === value);
                    if (!repo || !connection.connected) return;
                    onSelectionChange({
                      installationId: connection.installationId,
                      fullName: repo.fullName,
                      defaultBranch: repo.defaultBranch,
                      branch: repo.defaultBranch,
                    });
                  }}
                >
                  <SelectTrigger id="github-repo" className="h-11 w-full">
                    <SelectValue placeholder="Choose a repository">
                      {selectedRepo
                        ? repoLabel(selectedRepo.fullName, selectedRepo.private)
                        : "Choose a repository"}
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    {repos.map((repo) => (
                      <SelectItem key={repo.id} value={repo.fullName}>
                        {repoLabel(repo.fullName, repo.private)}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <p className="text-xs text-muted-foreground">
                  The agent opens pull requests in this repository.
                </p>
              </div>

              {selection ? (
                <div className="grid gap-2">
                  <Label htmlFor="github-branch">Branch</Label>
                  <Select
                    value={selection.branch}
                    onValueChange={(branch) =>
                      onSelectionChange({ ...selection, branch })
                    }
                  >
                    <SelectTrigger id="github-branch" className="h-11 w-full">
                      <SelectValue placeholder="Choose a branch">
                        {selection.branch}
                      </SelectValue>
                    </SelectTrigger>
                    <SelectContent>
                      {branchNames.map((branch) => (
                        <SelectItem key={branch} value={branch}>
                          {branch}
                          {branch === selection.defaultBranch ? " · default" : ""}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <p className="text-xs text-muted-foreground">
                    {branchesLoading
                      ? "Loading branches…"
                      : "Pull requests open against this branch."}
                  </p>
                </div>
              ) : null}
            </>
          )}
        </div>
      ) : loading ? null : (
        <div className="grid gap-3">
          <Button
            type="button"
            variant="outline"
            className="h-14 w-full justify-start px-4"
            disabled={authorizing}
            onClick={connect}
          >
            <GithubIcon />
            {authorizing ? "Waiting for GitHub…" : "Connect GitHub"}
          </Button>
          <p className="text-xs text-muted-foreground">
            Install the Friction Fixer app on one repository.
          </p>
        </div>
      )}

      {error ? (
        <p
          className="rounded-md bg-destructive/10 px-3 py-2 text-sm text-destructive"
          role="alert"
        >
          {error}
        </p>
      ) : null}

      <div className="flex items-center justify-between gap-4 rounded-lg border border-border px-4 py-3">
        <div>
          <p className="text-sm font-semibold">
            Review changes before they go live
          </p>
          <p className="mt-1 text-sm text-muted-foreground">
            You approve. The agent measures.
          </p>
        </div>
        <Check size={18} className="shrink-0 text-success" />
      </div>
    </div>
  );
}

function repoLabel(fullName: string, isPrivate: boolean) {
  return isPrivate ? `${fullName} (private)` : fullName;
}

function isInstallMessage(value: unknown): value is GithubInstallMessage {
  return (
    typeof value === "object" &&
    value !== null &&
    "type" in value &&
    value.type === GITHUB_INSTALL_MESSAGE
  );
}

async function readJson<T>(path: string): Promise<T> {
  const response = await fetch(path, { cache: "no-store" });
  const body = (await response.json().catch(() => ({}))) as {
    error?: string;
  } & T;
  if (!response.ok) {
    throw new Error(body.error || "Could not reach GitHub.");
  }
  return body;
}

function messageFrom(error: unknown) {
  return error instanceof Error ? error.message : "Could not reach GitHub.";
}

